SELECT ?film ?filmLabel ?director ?directorLabel WHERE {
  VALUES ?film { dbr:High_Wall dbr:Love_by_Request }
  ?film dbo:director ?director .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

SELECT ?film ?director WHERE {
  VALUES ?film { dbr:High_Wall dbr:Love_by_Request }
  ?film dbo:director ?director .
}

SELECT ?director ?directorLabel ?deathDate ?deathDateAlt WHERE {
  VALUES ?director { dbr:Curtis_Bernhardt dbr:Sergey_Mikaelyan }
  OPTIONAL { ?director dbo:deathDate ?deathDate. }
  OPTIONAL { ?director dbp:deathDate ?deathDateAlt. }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), 'EN')) }
}

SELECT ?director ?deathDate WHERE {
  BIND(dbr:Curtis_Bernhardt AS ?director)
  OPTIONAL { ?director dbo:deathDate ?deathDate. }
}

SELECT ?director ?deathDate WHERE {
  BIND(dbr:Sergey_Mikaelyan AS ?director)
  OPTIONAL { ?director dbo:deathDate ?deathDate. }
}

